// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Initial owner is address(0); only address(0) passes onlyOwner.
        vm.assume(newOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // Rule: after ownership transfer, the new owner is exactly newOwner.
        assertTrue(c.owner() == newOwner);
    }
}
